// Primitive types: pass-by-value is clean and efficient
int maxVal(int a, int b) {
    return (a > b) ? a : b;
}

// Heavy object types: pass-by-const-reference prevents expensive copying
void printSummary(const std::string& title, int value) {
    std::cout << title << ": " << value << "\n";
}

int main() {
    int x = 42;
    int y = 99;
    int m = maxVal(x, y);

    std::string label = "Maximum";
    printSummary(label, m);

    return 0;
}

#include <iostream>
#include <string>
#include <cctype>

int hexCharToDecimal(char ch) {
    ch = static_cast<char>(std::toupper(static_cast<unsigned char>(ch)));
    if (ch >= 'A' && ch <= 'F') {
        return 10 + (ch - 'A');
    }
    return ch - '0';
}

int hex2Dec(const std::string& hex) {
    int decimalValue = 0;
    for (char ch : hex) {
        decimalValue = decimalValue * 16 + hexCharToDecimal(ch);
    }
    return decimalValue;
}

int main() {
    std::string hex1 = "AB8C";
    std::string hex2 = "af71";

    std::cout << "Decimal of " << hex1 << ": " << hex2Dec(hex1) << "\n";
    std::cout << "Decimal of " << hex2 << ": " << hex2Dec(hex2) << "\n";

    return 0;
}

#include <iostream>

// Top-level decomposition demo using clean functional abstractions
void printMonthTitle(int year, int month) {
    std::cout << "=== Calendar for " << month << "/" << year << " ===\n";
    std::cout << "Sun Mon Tue Wed Thu Fri Sat\n";
}

void printMonthBody(int /*year*/, int /*month*/) {
    // Implementation stub illustrating modular separation
    std::cout << "                  1   2   3\n";
    std::cout << "  4   5   6   7   8   9  10\n";
}

void printMonth(int year, int month) {
    printMonthTitle(year, month);
    printMonthBody(year, month);
}

int main() {
    int year = 2013;
    int month = 8;
    printMonth(year, month);
    return 0;
}
